def encode_cyclic(s: str):
    """
    Returns encoded string by cycling groups of three characters.
    """
    # Split the string into groups of 3 (last group may be shorter)
    groups = [s[i:i+3] for i in range(0, len(s), 3)]
    # For each group of 3, rotate left by one (move first char to end)
    encoded_groups = []
    for group in groups:
        if len(group) == 3:
            encoded_groups.append(group[1] + group[2] + group[0])
        else:
            encoded_groups.append(group)  # For groups with <3 chars, leave as is
    return "".join(encoded_groups)

def decode_cyclic(s: str):
    """
    Decodes a string that was encoded with encode_cyclic.
    The encoding shifts the first character of each 3-char group to the end,
    so to decode, shift it back (i.e., move last char to front for full groups).
    """
    groups = [s[i:i+3] for i in range(0, len(s), 3)]
    decoded_groups = []
    for group in groups:
        if len(group) == 3:
            # Shift right by one (move last char to front)
            decoded_groups.append(group[-1] + group[:-1])
        else:
            decoded_groups.append(group)
    return "".join(decoded_groups)
