import string

def encode_shift(s: str) -> str:
    """
    Returns encoded string by shifting every alphabetic character by 5 positions forward in the alphabet.
    Non-alphabetic characters are left unchanged.
    """
    result = []
    for ch in s:
        if ch.isalpha():
            base = ord('a') if ch.islower() else ord('A')
            shifted = (ord(ch) - base + 5) % 26 + base
            result.append(chr(shifted))
        else:
            result.append(ch)
    return "".join(result)

def decode_shift(s: str) -> str:
    """
    Takes as input a string encoded with encode_shift and returns the decoded original string.
    """
    result = []
    for ch in s:
        if ch.isalpha():
            base = ord('a') if ch.islower() else ord('A')
            shifted = (ord(ch) - base - 5) % 26 + base
            result.append(chr(shifted))
        else:
            result.append(ch)
    return "".join(result)
