import re

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ','. If neither exist, return the number of lower-case letters with odd order in the
    alphabet (ord('a') = 0, ..., ord('z') = 25).
    '''
    # Check for whitespace first
    if ' ' in txt:
        # Split on any whitespace (spaces, tabs, newlines)
        return re.split(r'\s+', txt.strip())
    elif ',' in txt:
        # Split on commas, strip whitespace around each part
        return [part.strip() for part in txt.split(',')]
    else:
        # Count lowercase letters with odd alphabetical order (a=0 even, b=1 odd, ..., z=25)
        count = 0
        for c in txt:
            if 'a' <= c <= 'z' and (ord(c) - ord('a')) % 2 == 1:
                count += 1
        return count
