def largest_smallest_integers(lst):
    """
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of the negative integers and 'b' is the smallest
    of the positive integers in the list. If there are no negative or
    positive integers respectively, return None for that part.

    Parameters:
    lst (list): List of integers

    Returns:
    tuple: (largest_negative, smallest_positive) or (None, None) if not found
    """
    largest_neg = None
    smallest_pos = None

    for num in lst:
        if num < 0:
            if largest_neg is None or num > largest_neg:
                largest_neg = num
        elif num > 0:
            if smallest_pos is None or num < smallest_pos:
                smallest_pos = num

    return (largest_neg, smallest_pos)
