def compare_one(a, b):
    """
    Compare two values that can be int, float, or string representations of real numbers.
    Returns the larger value in its original type, or None if they are equal.
    """
    # Helper to convert string numbers (with comma as thousand separator) to float
    def to_number(x):
        try:
            if isinstance(x, str):
                # Remove commas and try to convert to float
                return float(x.replace(',', ''))
            else:
                return float(x)
        except ValueError:
            # If conversion fails (invalid string), keep original (for type comparison)
            return x

    num_a = to_number(a)
    num_b = to_number(b)

    if num_a > num_b:
        # Return original type of a
        if isinstance(a, str):
            return a
        else:
            return a
    elif num_b > num_a:
        # Return original type of b
        if isinstance(b, str):
            return b
        else:
            return b
    else:
        return None
