import math

def words_in_sentence(sentence: str) -> str:
    """
    Returns a string containing the words from the input sentence whose lengths are prime numbers,
    preserving their original order. Words are separated by whitespace in the input.
    """
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    # Split the sentence into words (handles multiple spaces as well)
    words = sentence.split()
    filtered = [w for w in words if is_prime(len(w))]
    return " ".join(filtered)
